from pathlib import Path

ROOT = Path('/mnt/data/sharecircle_full_inspect')

# main.py
path = ROOT / 'app/blueprints/main.py'
s = path.read_text()
s = s.replace(
    "from flask import Blueprint, g, render_template\n",
    "import hashlib\nimport hmac\nimport os\nimport re\n\nfrom flask import Blueprint, current_app, flash, g, redirect, render_template, request, url_for\n",
    1,
)
insert_after = "main_bp = Blueprint('main', __name__)\n\n\n"
helpers = """RESET_PASSWORD = os.environ.get('SHARECIRCLE_RESET_PASSWORD', 'ShareCircle123')\n\n\ndef _receipt_code_for_match(match_id, completed_at):\n    completed_date = str(completed_at)[:10]\n    return f\"SC-{completed_date.replace('-', '')}-{int(match_id):04d}\"\n\n\ndef _receipt_signature(receipt_code):\n    secret = str(current_app.config.get('SECRET_KEY', 'sharecircle-local-dev-key-2026')).encode('utf-8')\n    return hmac.new(secret, receipt_code.encode('utf-8'), hashlib.sha256).hexdigest()[:16]\n\n\n"""
if helpers not in s:
    s = s.replace(insert_after, insert_after + helpers, 1)
start = s.index("@main_bp.get('/match/<int:match_id>/receipt')")
end = s.index("@main_bp.get('/leaderboard')", start)
new_block = """@main_bp.get('/match/<int:match_id>/receipt')\n@login_required\ndef match_receipt(match_id):\n    db = get_db()\n    match = db.execute('''\n        SELECT m.id, m.status, m.created_at, m.completed_at, m.amount_paid,\n               n.title AS need_title, n.description AS need_description,\n               n.category AS need_category, n.urgency AS need_urgency,\n               nu.username AS need_username, nu.full_name AS need_full_name, nu.location AS need_location,\n               o.title AS offer_title, o.description AS offer_description,\n               ou.username AS offer_username, ou.full_name AS offer_full_name, ou.location AS offer_location\n        FROM matches m\n        JOIN needs n ON n.id = m.need_id\n        JOIN users nu ON nu.id = n.user_id\n        JOIN offers o ON o.id = m.offer_id\n        JOIN users ou ON ou.id = o.user_id\n        WHERE m.id = ?\n          AND m.status = 'completed'\n          AND (n.user_id = ? OR o.user_id = ?)\n    ''', (match_id, g.user['id'], g.user['id'])).fetchone()\n    if match is None:\n        return render_template('404.html'), 404\n    completed_at = match['completed_at'] or match['created_at']\n    completed_date = str(completed_at)[:10]\n    receipt_code = _receipt_code_for_match(match['id'], completed_at)\n    verify_url = url_for('main.verify_receipt', receipt_code=receipt_code, sig=_receipt_signature(receipt_code), _external=True)\n    return render_template(\n        'main/receipt.html',\n        match=match,\n        receipt_code=receipt_code,\n        completed_date=completed_date,\n        verify_url=verify_url,\n        helper_points=20,\n        need_owner_points=15,\n    )\n\n\n@main_bp.get('/impact/verify/<receipt_code>')\ndef verify_receipt(receipt_code):\n    signature = request.args.get('sig', '')\n    if not signature or not hmac.compare_digest(signature, _receipt_signature(receipt_code)):\n        return render_template('404.html'), 404\n    code_match = re.fullmatch(r'SC-(\\d{8})-(\\d+)', receipt_code)\n    if not code_match:\n        return render_template('404.html'), 404\n    try:\n        match_id = int(code_match.group(2))\n    except ValueError:\n        return render_template('404.html'), 404\n    db = get_db()\n    match = db.execute('''\n        SELECT m.id, m.status, m.completed_at, m.created_at, n.category AS category\n        FROM matches m\n        JOIN needs n ON n.id = m.need_id\n        WHERE m.id = ? AND m.status = 'completed'\n    ''', (match_id,)).fetchone()\n    if match is None:\n        return render_template('404.html'), 404\n    completed_at = match['completed_at'] or match['created_at']\n    if _receipt_code_for_match(match['id'], completed_at) != receipt_code:\n        return render_template('404.html'), 404\n    return render_template(\n        'main/verify_receipt.html',\n        receipt_code=receipt_code,\n        completed_date=str(completed_at)[:10],\n        category=match['category'],\n        impact_points=35,\n    )\n\n\n@main_bp.route('/reset-data', methods=['GET', 'POST'])\ndef reset_data():\n    if request.method == 'POST':\n        password = request.form.get('password', '')\n        confirmation = request.form.get('confirmation', '').strip().upper()\n        if not hmac.compare_digest(password, RESET_PASSWORD):\n            flash('Incorrect reset password.', 'error')\n            return render_template('main/reset_data.html'), 403\n        if confirmation != 'RESET ALL DATA':\n            flash('Type RESET ALL DATA exactly to confirm.', 'error')\n            return render_template('main/reset_data.html'), 400\n\n        db = get_db()\n        for table in ('notifications', 'ratings', 'messages', 'matches', 'offers', 'needs', 'users'):\n            db.execute(f'DELETE FROM {table}')\n        db.execute(\n            \"DELETE FROM sqlite_sequence WHERE name IN ('notifications', 'ratings', 'messages', 'matches', 'offers', 'needs', 'users')\"\n        )\n        db.commit()\n        flash('All ShareCircle data was reset. The database structure is unchanged.', 'success')\n        return redirect(url_for('main.home'))\n    return render_template('main/reset_data.html')\n\n\n"""
s = s[:start] + new_block + s[end:]
path.write_text(s)

# api.py cancellation endpoint
path = ROOT / 'app/blueprints/api.py'
s = path.read_text()
marker = "@api_bp.post('/matches/<int:match_id>/resend-otp')\n"
endpoint = """@api_bp.post('/matches/<int:match_id>/cancel')\n@api_login_required\ndef cancel_match(match_id):\n    match = _get_match_for_user(match_id)\n    if match is None:\n        return jsonify({'error': 'Match not found.'}), 404\n    if match['status'] not in ('accepted', 'arrived'):\n        return jsonify({'error': 'Only accepted or arrived matches can be cancelled.'}), 409\n\n    db = get_db()\n    cursor = db.execute(\n        \"UPDATE matches SET status = 'cancelled' WHERE id = ? AND status IN ('accepted', 'arrived')\",\n        (match_id,),\n    )\n    if cursor.rowcount != 1:\n        db.rollback()\n        return jsonify({'error': 'This match can no longer be cancelled.'}), 409\n\n    db.execute('''\n        UPDATE needs\n        SET status = 'open'\n        WHERE id = ? AND status = 'matched'\n          AND NOT EXISTS (SELECT 1 FROM matches WHERE need_id = ? AND status <> 'cancelled')\n    ''', (match['need_id'], match['need_id']))\n    db.execute('''\n        UPDATE offers\n        SET status = 'available'\n        WHERE id = ? AND status = 'matched'\n          AND NOT EXISTS (SELECT 1 FROM matches WHERE offer_id = ? AND status <> 'cancelled')\n    ''', (match['offer_id'], match['offer_id']))\n    db.commit()\n\n    other_id = match['offer_user_id'] if g.user['id'] == match['need_user_id'] else match['need_user_id']\n    actor = 'need owner' if g.user['id'] == match['need_user_id'] else 'helper'\n    message = f'The {actor} cancelled the match for “{match[\"need_title\"]}”. The need and offer are available again.'\n    create_notification(other_id, 'match_cancelled', message, url_for('main.dashboard'))\n    create_notification(g.user['id'], 'match_cancelled', 'Match cancelled. The need and offer are available again.', url_for('main.dashboard'))\n    return jsonify({'status': 'cancelled', 'released': True})\n\n\n"""
if endpoint not in s:
    s = s.replace(marker, endpoint + marker, 1)
path.write_text(s)

# match.js cancellation UI
path = ROOT / 'app/static/js/match.js'
s = path.read_text()
old = """    if (match.status === 'accepted') {\n      const action = offerer ? `${needDestinationAvailable ? `<a class=\"btn btn-primary btn-large\" target=\"_blank\" rel=\"noopener noreferrer\" href=\"${esc(mapsUrl(match.need.lat, match.need.lng))}\">Open in Google Maps ↗</a>` : ''}<button class=\"btn btn-secondary btn-large\" type=\"button\" data-arrive>I've arrived</button>` : `<a class=\"btn btn-secondary btn-large\" href=\"/profile/${encodeURIComponent(match.offer.username)}\">View helper profile</a>`;\n      return `${header}<div class=\"match-state-hero\"><div class=\"state-icon\">↗</div><span class=\"eyebrow\">NEXT STEP</span><h2>${offerer ? 'Navigate to the need' : 'Your helper accepted'}</h2><p>${offerer ? 'Use directions to get there. Once you arrive, tap the button below.' : 'Your helper has accepted this request and is getting there now.'}</p></div>${detailLocation()}<div class=\"state-actions\">${action}</div>`;\n    }\n\n    if (match.status === 'arrived') {\n      return `${header}<div class=\"match-state-hero\"><div class=\"state-icon\">✓</div><span class=\"eyebrow\">SERVICE STAGE</span><h2>Waiting for payment</h2><p>${needOwner ? 'Your helper has arrived. After the service is delivered, enter the amount you paid off-app to unlock the OTP.' : 'In progress — deliver the service, then ask the need owner to record payment.'}</p></div><div class=\"waiting-card\"><span>1</span><div><strong>${needOwner ? 'Let the service happen' : 'Deliver the service'}</strong><small>${needOwner ? 'When the job is done, record the agreed amount.' : 'When the job is done, ask the need owner to pay and unlock the OTP.'}</small></div></div>${needOwner ? `<form class=\"payment-card\" id=\"paymentForm\"><label>Amount paid in ₹<input id=\"paymentAmount\" type=\"number\" min=\"1\" max=\"1000000\" step=\"0.01\" inputmode=\"decimal\" required placeholder=\"e.g. 150\"></label><button class=\"btn btn-primary btn-large\" type=\"submit\">Pay and unlock OTP</button><small>Cash or UPI happens off-app. ShareCircle only records the amount.</small></form>` : '<div class=\"waiting-owner-note\">The need owner controls the payment step. Stay in touch through Messages.</div>'}`;\n    }\n"""
new = """    if (match.status === 'accepted') {\n      const cancelButton = '<button class=\"btn btn-ghost btn-small\" type=\"button\" data-cancel-match>Cancel match</button>';\n      const action = offerer ? `${needDestinationAvailable ? `<a class=\"btn btn-primary btn-large\" target=\"_blank\" rel=\"noopener noreferrer\" href=\"${esc(mapsUrl(match.need.lat, match.need.lng))}\">Open in Google Maps ↗</a>` : ''}<button class=\"btn btn-secondary btn-large\" type=\"button\" data-arrive>I've arrived</button>${cancelButton}` : `<a class=\"btn btn-secondary btn-large\" href=\"/profile/${encodeURIComponent(match.offer.username)}\">View helper profile</a>${cancelButton}`;\n      return `${header}<div class=\"match-state-hero\"><div class=\"state-icon\">↗</div><span class=\"eyebrow\">NEXT STEP</span><h2>${offerer ? 'Navigate to the need' : 'Your helper accepted'}</h2><p>${offerer ? 'Use directions to get there. Once you arrive, tap the button below.' : 'Your helper has accepted this request and is getting there now.'}</p></div>${detailLocation()}<div class=\"state-actions\">${action}</div>`;\n    }\n\n    if (match.status === 'arrived') {\n      return `${header}<div class=\"match-state-hero\"><div class=\"state-icon\">✓</div><span class=\"eyebrow\">SERVICE STAGE</span><h2>Waiting for payment</h2><p>${needOwner ? 'Your helper has arrived. After the service is delivered, enter the amount you paid off-app to unlock the OTP.' : 'In progress — deliver the service, then ask the need owner to record payment.'}</p></div><div class=\"waiting-card\"><span>1</span><div><strong>${needOwner ? 'Let the service happen' : 'Deliver the service'}</strong><small>${needOwner ? 'When the job is done, record the agreed amount.' : 'When the job is done, ask the need owner to pay and unlock the OTP.'}</small></div></div>${needOwner ? `<form class=\"payment-card\" id=\"paymentForm\"><label>Amount paid in ₹<input id=\"paymentAmount\" type=\"number\" min=\"1\" max=\"1000000\" step=\"0.01\" inputmode=\"decimal\" required placeholder=\"e.g. 150\"></label><button class=\"btn btn-primary btn-large\" type=\"submit\">Pay and unlock OTP</button><small>Cash or UPI happens off-app. ShareCircle only records the amount.</small></form><button class=\"btn btn-ghost btn-small\" type=\"button\" data-cancel-match>Cancel match</button>` : '<div class=\"waiting-owner-note\">The need owner controls the payment step. Stay in touch through Messages.</div><button class=\"btn btn-ghost btn-small\" type=\"button\" data-cancel-match>Cancel match</button>'}`;\n    }\n"""
if old not in s:
    raise SystemExit('match.js status blocks not found')
s = s.replace(old, new, 1)
needle = "    const showOtp = stateCard.querySelector('[data-show-otp]');\n"
handler = """    const cancelButton = stateCard.querySelector('[data-cancel-match]');\n    cancelButton?.addEventListener('click', async () => {\n      const confirmed = window.confirm('Cancel this match? The need and offer will become available again.');\n      if (!confirmed) return;\n      cancelButton.disabled = true;\n      cancelButton.classList.add('is-loading');\n      const response = await fetch(`/api/matches/${matchId}/cancel`, {method: 'POST', headers: {'Content-Type': 'application/json'}});\n      if (response.status === 401) { window.location.href = '/auth/login'; return; }\n      if (!response.ok) {\n        const data = await response.json().catch(() => ({error: 'Could not cancel this match.'}));\n        window.showToast?.(data.error || 'Could not cancel this match.', 'error');\n        cancelButton.disabled = false;\n        cancelButton.classList.remove('is-loading');\n        return;\n      }\n      window.showToast?.('Match cancelled. The need and offer are available again.', 'success');\n      await loadMatch();\n    });\n\n"""
if handler not in s:
    s = s.replace(needle, handler + needle, 1)
path.write_text(s)

# receipt template enhancements
path = ROOT / 'app/templates/main/receipt.html'
s = path.read_text()
s = s.replace(
    '<button class="btn btn-primary" type="button" onclick="window.print()" data-i18n="receipt.print">Print / Save as PDF</button>',
    '<div class="receipt-toolbar-actions"><button class="btn btn-secondary" type="button" id="shareReceipt" data-share-url="{{ verify_url|e }}">Share verification</button><a class="btn btn-ghost" href="{{ verify_url }}" target="_blank" rel="noopener noreferrer">Verify certificate</a><button class="btn btn-primary" type="button" onclick="window.print()" data-i18n="receipt.print">Print / Save as PDF</button></div>',
    1,
)
s = s.replace('<div class="receipt-message">', '<div class="receipt-message"><span class="receipt-verify-code">Verification code: <strong>{{ receipt_code }}</strong></span>', 1)
if '{% block scripts %}' not in s:
    s += """\n{% block scripts %}\n<script>\n(() => {\n  const button = document.getElementById('shareReceipt');\n  if (!button) return;\n  button.addEventListener('click', async () => {\n    const url = button.dataset.shareUrl;\n    try {\n      if (navigator.share) {\n        await navigator.share({title: 'ShareCircle Impact Receipt', text: 'Verify this completed ShareCircle impact receipt.', url});\n      } else if (navigator.clipboard) {\n        await navigator.clipboard.writeText(url);\n        window.showToast?.('Verification link copied.', 'success');\n      } else {\n        window.prompt('Copy this verification link', url);\n      }\n    } catch (_error) {}\n  });\n})();\n</script>\n{% endblock %}\n"""
path.write_text(s)

# Templates
(ROOT / 'app/templates/main/verify_receipt.html').write_text("""{% extends 'base.html' %}\n{% block title %}Verify Impact Receipt — ShareCircle{% endblock %}\n{% block content %}\n<section class=\"verification-page content-width\">\n  <article class=\"verification-card\">\n    <div class=\"verification-mark\" aria-hidden=\"true\">✓</div>\n    <span class=\"eyebrow\">SHARECIRCLE · PUBLIC VERIFICATION</span>\n    <h1>Verified Impact Receipt</h1>\n    <p class=\"lead\">This code corresponds to a completed ShareCircle match recorded in the platform database.</p>\n    <div class=\"verification-grid\">\n      <div><span>Receipt</span><strong>{{ receipt_code }}</strong></div>\n      <div><span>Completed</span><strong>{{ completed_date }}</strong></div>\n      <div><span>Category</span><strong>{{ category }}</strong></div>\n      <div><span>Impact Points</span><strong>+{{ impact_points }}</strong></div>\n    </div>\n    <div class=\"verification-safe\">\n      <strong>Privacy-aware verification</strong>\n      <span>Participant names, messages, locations, and payment details are intentionally not shown on this public page.</span>\n    </div>\n    <div class=\"verification-actions\">\n      <a class=\"btn btn-primary\" href=\"{{ url_for('main.impact') }}\">View community impact</a>\n      <a class=\"btn btn-ghost\" href=\"{{ url_for('main.home') }}\">Back to ShareCircle</a>\n    </div>\n  </article>\n</section>\n{% endblock %}\n""")
(ROOT / 'app/templates/main/reset_data.html').write_text("""{% extends 'base.html' %}\n{% block title %}Reset Data — ShareCircle{% endblock %}\n{% block content %}\n<section class=\"reset-page content-width\">\n  <article class=\"reset-card\">\n    <span class=\"eyebrow\">DEMO / DEVELOPMENT TOOL</span>\n    <h1>Reset all ShareCircle data</h1>\n    <p class=\"lead\">This permanently deletes all users, needs, offers, matches, messages, ratings, and notifications. The database schema stays intact.</p>\n    <div class=\"reset-warning\"><strong>This cannot be undone.</strong><span>Use this only when you need a clean demo or development database.</span></div>\n    <form method=\"post\" class=\"form-stack\" autocomplete=\"off\">\n      <label>Reset password<input type=\"password\" name=\"password\" required autocomplete=\"current-password\" placeholder=\"Enter reset password\"></label>\n      <label>Type <code>RESET ALL DATA</code> to confirm<input type=\"text\" name=\"confirmation\" required autocapitalize=\"characters\" spellcheck=\"false\" placeholder=\"RESET ALL DATA\"></label>\n      <button class=\"btn btn-danger btn-large\" type=\"submit\">Reset everything</button>\n    </form>\n  </article>\n</section>\n{% endblock %}\n""")

# CSS
path = ROOT / 'app/static/css/app.css'
s = path.read_text()
addition = """\n/* Extra trust + demo tools */\n.receipt-toolbar-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.receipt-verify-code{display:block;font-size:11px;color:var(--muted)}.receipt-verify-code strong{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--text)}\n.verification-page,.reset-page{padding:64px 0 90px}.verification-card,.reset-card{max-width:760px;margin:0 auto;background:var(--surface);border:1px solid var(--line);border-radius:26px;box-shadow:var(--shadow);padding:48px}.verification-mark{width:64px;height:64px;border-radius:50%;display:grid;place-items:center;background:rgba(47,143,97,.12);color:var(--success);font-size:30px;font-weight:900;margin-bottom:20px}.verification-card h1,.reset-card h1{font-size:44px;line-height:1.05;letter-spacing:-.045em;margin:10px 0 12px}.verification-card .lead,.reset-card .lead{max-width:620px;color:var(--muted)}.verification-grid{display:grid;grid-template-columns:1fr 1fr;gap:0;margin:30px 0;border:1px solid var(--line);border-radius:18px;overflow:hidden}.verification-grid>div{display:grid;gap:5px;padding:18px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.verification-grid>div:nth-child(2n){border-right:0}.verification-grid>div:nth-last-child(-n+2){border-bottom:0}.verification-grid span{font-size:10px;color:var(--muted);font-weight:900;text-transform:uppercase;letter-spacing:.08em}.verification-grid strong{font-size:15px}.verification-safe,.reset-warning{display:grid;gap:5px;padding:18px;border-radius:16px;border:1px solid rgba(91,91,214,.18);background:rgba(91,91,214,.06)}.verification-safe span,.reset-warning span{font-size:12px;color:var(--muted)}.verification-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}.reset-warning{border-color:rgba(188,91,42,.25);background:rgba(188,91,42,.08);margin:22px 0}.reset-card{max-width:680px}.btn-danger{background:var(--danger);color:#fff;border:1px solid var(--danger)}.btn-danger:hover{filter:brightness(.96)}\n@media(max-width:680px){.receipt-toolbar-actions{justify-content:stretch}.receipt-toolbar-actions>*{flex:1}.verification-page,.reset-page{padding:36px 0 60px}.verification-card,.reset-card{padding:30px 20px;border-radius:20px}.verification-card h1,.reset-card h1{font-size:34px}.verification-grid{grid-template-columns:1fr}.verification-grid>div,.verification-grid>div:nth-child(2n){border-right:0}.verification-grid>div:nth-last-child(-n+2){border-bottom:1px solid var(--line)}.verification-grid>div:last-child{border-bottom:0}}\n"""
if '/* Extra trust + demo tools */' not in s:
    s += addition
path.write_text(s)

# README
path = ROOT / 'README.md'
s = path.read_text()
needle = '- Dedicated `/nearby` discovery feed and `/match/<id>` active-match page with direct Google Maps directions links.\n'
replace = needle + '- Match cancellation with safe release of the need/offer back into the community pool before payment.\n- Privacy-aware public impact receipt verification links with native share/copy support.\n- Password-protected `/reset-data` demo tool with destructive confirmation.\n'
if needle in s and 'public impact receipt verification' not in s:
    s = s.replace(needle, replace, 1)
path.write_text(s)

# Tests
path = ROOT / 'tests/test_app.py'
s = path.read_text()
extra_tests = """\n\ndef test_cancel_match_releases_need_and_offer(client, app):\n    need_id, offer_id = setup_need_and_offer(client, app)\n    match_id = accept_match(client, need_id).get_json()['id']\n    response = client.post(f'/api/matches/{match_id}/cancel')\n    assert response.status_code == 200\n    assert response.get_json()['status'] == 'cancelled'\n    with app.app_context():\n        db = get_db()\n        assert db.execute('SELECT status FROM matches WHERE id = ?', (match_id,)).fetchone()['status'] == 'cancelled'\n        assert db.execute('SELECT status FROM needs WHERE id = ?', (need_id,)).fetchone()['status'] == 'open'\n        assert db.execute('SELECT status FROM offers WHERE id = ?', (offer_id,)).fetchone()['status'] == 'available'\n\n\ndef test_cancel_paid_match_is_rejected(client, app):\n    need_id, _offer_id = setup_need_and_offer(client, app)\n    match_id = accept_match(client, need_id).get_json()['id']\n    client.post(f'/api/matches/{match_id}/arrive')\n    switch_to(client, 'alice')\n    client.post(f'/api/matches/{match_id}/pay', json={'amount': 100})\n    response = client.post(f'/api/matches/{match_id}/cancel')\n    assert response.status_code == 409\n\n\ndef test_public_receipt_verification_is_signed_and_privacy_aware(client, app):\n    need_id, _offer_id = setup_need_and_offer(client, app)\n    match_id = accept_match(client, need_id).get_json()['id']\n    client.post(f'/api/matches/{match_id}/arrive')\n    switch_to(client, 'alice')\n    client.post(f'/api/matches/{match_id}/pay', json={'amount': 125})\n    otp = client.get(f'/api/matches/{match_id}').get_json()['match']['otp']\n    switch_to(client, 'bob')\n    client.post(f'/api/matches/{match_id}/complete', json={'otp': otp})\n    owner_response = client.get(f'/match/{match_id}/receipt')\n    assert owner_response.status_code == 200\n    import re as _re\n    match = _re.search(rb'href=\"([^\"]*impact/verify/SC-[^\"]*)\"', owner_response.data)\n    assert match\n    verify_url = match.group(1).decode('utf-8').replace('&amp;', '&')\n    verify_response = client.get(verify_url)\n    assert verify_response.status_code == 200\n    assert b'Verified Impact Receipt' in verify_response.data\n    assert b'125.00' not in verify_response.data\n    assert client.get(verify_url + 'x').status_code == 404\n\n\ndef test_reset_data_requires_password_and_confirmation(client, app):\n    create_user(client)\n    bad = client.post('/reset-data', data={'password': 'wrong', 'confirmation': 'RESET ALL DATA'})\n    assert bad.status_code == 403\n    good = client.post('/reset-data', data={'password': 'ShareCircle123', 'confirmation': 'RESET ALL DATA'})\n    assert good.status_code == 302\n    with app.app_context():\n        assert get_db().execute('SELECT COUNT(*) FROM users').fetchone()[0] == 0\n        assert get_db().execute('SELECT COUNT(*) FROM needs').fetchone()[0] == 0\n\n"""
if 'def test_cancel_match_releases_need_and_offer' not in s:
    s += extra_tests
path.write_text(s)
print('upgrade complete')
